import React from "react";
import { Link, useNavigate } from "react-router-dom";
import { ShoppingBag, User, LogOut, Sun, Moon } from "lucide-react";
import { useCart } from "../context/CartContext";
import { useAuth } from "../context/AuthContext";
import { useTheme } from "../context/ThemeContext";

export default function Header({ onCartClick }) {
  const { count } = useCart();
  const { user, logout } = useAuth();
  const { theme, toggleTheme } = useTheme();
  const navigate = useNavigate();

  return (
    <header
      style={{
        position: "sticky",
        top: 0,
        zIndex: 40,
        background: "var(--card)",
        borderBottom: "1px solid var(--border)",
      }}
    >
      <div className="container" style={{ padding: "14px 24px", display: "flex", alignItems: "center", justifyContent: "space-between" }}>
        <Link to="/" className="focus-ring" style={{ display: "flex", alignItems: "center", gap: 9 }}>
          <span
            style={{
              width: 32,
              height: 32,
              borderRadius: 8,
              background: "var(--chili)",
              display: "flex",
              alignItems: "center",
              justifyContent: "center",
            }}
          >
            <TiffinMark />
          </span>
          <span className="disp" style={{ fontSize: 19, fontWeight: 700, color: "var(--ink)", letterSpacing: "-0.01em" }}>
            Healthy<span style={{ color: "var(--chili)" }}>Food</span>
          </span>
        </Link>

        <nav style={{ display: "flex", gap: 4, alignItems: "center" }}>
          <NavLink to="/menu">Menu</NavLink>
          <NavLink to="/orders">Track Order</NavLink>
          {user?.role === "admin" && <NavLink to="/admin">Admin</NavLink>}

          {user ? (
            <button
              onClick={() => {
                logout();
                navigate("/");
              }}
              className="focus-ring"
              title="Log out"
              style={{
                marginLeft: 8,
                display: "flex",
                alignItems: "center",
                gap: 6,
                padding: "8px 14px",
                borderRadius: 999,
                border: "1px solid var(--border)",
                background: "var(--panel)",
                fontSize: 13.5,
                fontWeight: 700,
                color: "var(--ink)",
              }}
            >
              <User size={15} /> {user.name.split(" ")[0]} <LogOut size={13} />
            </button>
          ) : (
            <NavLink to="/login">Log in</NavLink>
          )}

          <button
            onClick={toggleTheme}
            className="focus-ring"
            title={theme === "light" ? "Switch to dark theme" : "Switch to light theme"}
            style={{
              marginLeft: 8,
              width: 38,
              height: 38,
              borderRadius: "50%",
              border: "1px solid var(--border)",
              background: "var(--panel)",
              display: "flex",
              alignItems: "center",
              justifyContent: "center",
            }}
          >
            {theme === "light" ? <Moon size={16} color="var(--leaf)" /> : <Sun size={16} color="var(--turmeric)" />}
          </button>

          <button
            onClick={onCartClick}
            className="focus-ring"
            style={{
              position: "relative",
              marginLeft: 8,
              width: 38,
              height: 38,
              borderRadius: "50%",
              border: "1px solid var(--border)",
              background: "var(--panel)",
              display: "flex",
              alignItems: "center",
              justifyContent: "center",
            }}
          >
            <ShoppingBag size={17} color="var(--chili)" />
            {count > 0 && (
              <span
                style={{
                  position: "absolute",
                  top: -4,
                  right: -4,
                  background: "var(--chili)",
                  color: "#FFFFFF",
                  fontSize: 11,
                  fontWeight: 800,
                  borderRadius: 999,
                  minWidth: 18,
                  height: 18,
                  display: "flex",
                  alignItems: "center",
                  justifyContent: "center",
                  padding: "0 4px",
                }}
              >
                {count}
              </span>
            )}
          </button>
        </nav>
      </div>
    </header>
  );
}

function TiffinMark() {
  return (
    <svg width="17" height="17" viewBox="0 0 24 24" fill="none">
      <path d="M8 5 Q12 1 16 5" stroke="#FFFFFF" strokeWidth="2" strokeLinecap="round" />
      <rect x="6" y="4.5" width="12" height="2.4" rx="1.2" fill="#FFFFFF" />
      <rect x="5" y="7.2" width="14" height="5.4" rx="1.4" fill="#FFFFFF" />
      <rect x="5" y="13" width="14" height="5.4" rx="1.4" fill="#FFFFFF" opacity="0.75" />
      <rect x="4.3" y="12.2" width="15.4" height="1.6" rx="0.8" fill="var(--chili)" />
    </svg>
  );
}

function NavLink({ to, children }) {
  return (
    <Link
      to={to}
      className="focus-ring"
      style={{
        padding: "8px 14px",
        borderRadius: 999,
        fontSize: 14,
        fontWeight: 600,
        color: "var(--ink-soft)",
      }}
    >
      {children}
    </Link>
  );
}
